--! A reimplmentation of `lambdalisue/suda.vim` but only the Write feature.
local M = {}

--- Prompt for sudo password with masking, temporarily disabling cmdline autocompletion.
---@return string|nil password or nil if cancelled
function M.prompt_password()
  local has_blink, blink_cfg = pcall(require, "blink.cmp.config")
  local prev_blink
  if has_blink then
    prev_blink = blink_cfg.cmdline.enabled
    blink_cfg.cmdline.enabled = false
  end

  vim.fn.inputsave()
  local ok, pass = pcall(vim.fn.inputsecret, " Password: ")
  vim.fn.inputrestore()

  if has_blink and prev_blink ~= nil then
    blink_cfg.cmdline.enabled = prev_blink
  end

  if not ok or not pass or pass == "" then
    return nil
  end
  return pass
end

--- Check if sudo can execute commands without asking for password
---@return boolean
function M.can_sudo_non_interactive()
  local res = vim.system({ "sudo", "-n", "true" }):wait()
  return res.code == 0
end

--- Save buffer contents to file using sudo
---@param filepath? string Path to write to (defaults to current buffer file)
---@param bufnr? integer Buffer number (defaults to current buffer)
---@return boolean
function M.write(filepath, bufnr)
  bufnr = (bufnr == nil or bufnr == 0) and vim.api.nvim_get_current_buf() or bufnr

  if not filepath or filepath == "" then
    filepath = vim.api.nvim_buf_get_name(bufnr)
  end

  if not filepath or filepath == "" then
    vim.notify("No file name for current buffer", vim.log.levels.ERROR)
    return false
  end

  filepath = vim.fn.fnamemodify(filepath, ":p")

  -- Check if sudo password is required
  local password = nil
  if not M.can_sudo_non_interactive() then
    password = M.prompt_password()
    if not password then
      vim.notify("Sudo write cancelled", vim.log.levels.WARN)
      return false
    end
  end

  -- Write current buffer to a temporary file first
  -- This lets Neovim handle all fileencoding, format, BOM, and eol settings properly
  local tempfile = vim.fn.tempname()
  local write_ok, write_err = pcall(function()
    vim.api.nvim_buf_call(bufnr, function()
      vim.cmd("silent noautocmd write! " .. vim.fn.fnameescape(tempfile))
    end)
  end)

  if not write_ok then
    pcall(vim.fn.delete, tempfile)
    vim.notify("Failed to create temporary file: " .. tostring(write_err), vim.log.levels.ERROR)
    return false
  end

  -- Ensure parent directory exists
  local parent_dir = vim.fn.fnamemodify(filepath, ":h")
  if vim.fn.isdirectory(parent_dir) == 0 then
    local mkdir_cmd = { "sudo" }
    local stdin_mkdir = nil
    if password then
      vim.list_extend(mkdir_cmd, { "-S", "-p", "" })
      stdin_mkdir = password .. "\n"
    else
      table.insert(mkdir_cmd, "-n")
    end
    vim.list_extend(mkdir_cmd, { "mkdir", "-p", parent_dir })
    local m_res = vim.system(mkdir_cmd, { stdin = stdin_mkdir }):wait()
    if m_res.code ~= 0 then
      pcall(vim.fn.delete, tempfile)
      vim.notify("Failed to create directory: " .. (m_res.stderr or ""), vim.log.levels.ERROR)
      return false
    end
  end

  -- Use dd to write tempfile into target filepath in-place
  -- dd preserves existing inode permissions, owner, group, and symlinks
  local sudo_cmd = { "sudo" }
  local stdin_data = nil

  if password then
    vim.list_extend(sudo_cmd, { "-S", "-p", "" })
    stdin_data = password .. "\n"
  else
    table.insert(sudo_cmd, "-n")
  end

  vim.list_extend(sudo_cmd, { "dd", "if=" .. tempfile, "of=" .. filepath, "bs=1048576" })

  local res = vim.system(sudo_cmd, { stdin = stdin_data }):wait()
  pcall(vim.fn.delete, tempfile)

  if res.code ~= 0 then
    local err_msg = vim.trim(res.stderr or "")
    if err_msg:find("incorrect password") or err_msg:find("authentication failure") then
      vim.notify("Sudo authentication failed", vim.log.levels.ERROR)
    else
      vim.notify("Sudo write failed: " .. err_msg, vim.log.levels.ERROR)
    end
    return false
  end

  -- Mark buffer as clean and sync file modification time
  vim.bo[bufnr].modified = false
  vim.cmd("checktime " .. bufnr)

  local display_path = vim.fn.fnamemodify(filepath, ":~")
  vim.notify(string.format('"%s" written with sudo', display_path), vim.log.levels.INFO)
  return true
end

--- Setup Sudo commands
function M.setup()
  vim.api.nvim_create_user_command("SudoWrite", function(opts)
    local arg = opts.args ~= "" and opts.args or nil
    M.write(arg)
  end, {
    nargs = "?",
    complete = "file",
    desc = "Write buffer to file with sudo",
  })
end

return M
